let loader;
function loadHls(){return loader??=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='vendor/hls-1.6.13.min.js';s.onload=()=>resolve(window.Hls);s.onerror=()=>{loader=null;reject(Error('Não foi possível carregar o player.'))};document.head.append(s)})}
async function openLive(){
 const dialog=document.createElement('dialog');dialog.className='live-dialog';dialog.setAttribute('aria-labelledby','live-title');dialog.innerHTML=`<header><h2 id="live-title">Quadra 1 · Câmeras ao vivo</h2><button data-close aria-label="Fechar transmissão">✕</button></header><p>Transmissão atual da quadra, sem gravação das partidas anteriores.</p><div class="live-stage">${streams.map((_,i)=>`<div class="live-half"><video muted playsinline aria-label="Câmera ${i+1}"></video><span role="status">Câmera ${i+1} · conectando…</span></div>`).join('')}</div><div class="live-controls"><button data-play>Reproduzir</button><button data-sound>Ativar áudio da câmera 1</button><button data-full>Tela cheia</button><button data-retry>Reconectar</button></div><p class="subtle">Duas câmeras em um painel. Pode haver diferença de atraso entre as imagens. No celular, use na horizontal para ampliar o campo.</p>`;
 document.body.append(dialog);dialog.showModal();const videos=[...dialog.querySelectorAll('video')],players=[];let closed=false;
 const status=(i,text)=>{if(!closed)dialog.querySelectorAll('[role=status]')[i].textContent=`Câmera ${i+1} · ${text}`};
 const play=async()=>{const results=await Promise.allSettled(videos.map(v=>v.play()));results.forEach((r,i)=>{if(r.status==='rejected')status(i,'aguardando transmissão ou toque para reproduzir')})};
 const cleanup=()=>{if(closed)return;closed=true;players.forEach(p=>p.destroy());videos.forEach(v=>{v.pause();v.removeAttribute('src');v.load()});dialog.remove()};
 dialog.addEventListener('close',cleanup);dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.querySelector('[data-retry]').onclick=()=>{dialog.close();openLive()};
 dialog.querySelector('[data-play]').onclick=()=>{if(videos.some(v=>!v.paused)){videos.forEach(v=>v.pause());dialog.querySelector('[data-play]').textContent='Reproduzir'}else{play();dialog.querySelector('[data-play]').textContent='Pausar'}};
 dialog.querySelector('[data-sound]').onclick=e=>{videos[0].muted=!videos[0].muted;e.target.textContent=videos[0].muted?'Ativar áudio da câmera 1':'Silenciar áudio'};
 dialog.querySelector('[data-full]').onclick=async()=>{try{await dialog.querySelector('.live-stage').requestFullscreen()}catch{dialog.querySelector('[data-full]').textContent='Gire o celular para ampliar'}};
 try{const Hls=videos[0].canPlayType('application/vnd.apple.mpegurl')?null:await loadHls();if(closed)return;videos.forEach((v,i)=>{v.addEventListener('playing',()=>status(i,'transmitindo'));v.addEventListener('waiting',()=>status(i,'carregando…'));v.addEventListener('error',()=>status(i,'indisponível · tente reconectar'));if(Hls?.isSupported()){const p=new Hls({liveSyncDurationCount:3});players.push(p);p.on(Hls.Events.ERROR,(_,e)=>{if(e.fatal){status(i,'indisponível · tente reconectar');p.destroy()}});p.loadSource(streams[i]);p.attachMedia(v)}else if(!Hls)v.src=streams[i];else status(i,'navegador não compatível')});}catch{videos.forEach((_,i)=>status(i,'não foi possível carregar a transmissão'))}
}
